import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.DMvgf4hZ.js";const c=JSON.parse('{"title":"01 · 开发总览","description":"","frontmatter":{"title":"01 · 开发总览"},"headers":[],"relativePath":"plugins/overview.md","filePath":"plugins/overview.md","lastUpdated":1794884041000}'),l={name:"plugins/overview.md"};function e(p,s,o,d,h,r){return t(),i("div",null,[...s[0]||(s[0]=[n(`<h2 id="_1-选择扩展类型" tabindex="-1">1. 选择扩展类型 <a class="header-anchor" href="#_1-选择扩展类型" aria-label="Permalink to &quot;1. 选择扩展类型&quot;">​</a></h2><table tabindex="0"><thead><tr><th><strong>类型</strong></th><th><strong>适用场景</strong></th><th><strong>运行方式与交付物</strong></th></tr></thead><tbody><tr><td>tools</td><td>为 Agent 增加搜索、文件操作、网络请求、媒体处理等可调用能力。</td><td>Bun 服务端执行；分发 <code>&lt;name&gt;</code>.tool.js，可附带 Vue 消息组件。</td></tr><tr><td>nodes</td><td>增加画布交互组件、输入输出端口和节点操作。</td><td>浏览器或桌面 WebView 执行；分发 <code>&lt;name&gt;</code>.umd.js。</td></tr><tr><td>skill</td><td>约定任务流程、专业方法、输出要求与参考资料。</td><td>按需读取 SKILL.md 和资源，无需编译。</td></tr><tr><td>teams</td><td>组织多 Agent 的职责和协作。</td><td>未开放，见本文第五章。</td></tr></tbody></table><p>需要可执行操作时开发 tools，需要画布界面时开发 nodes，已有操作能力足够、只需明确流程时开发 skill。三类扩展可配合使用。</p><h2 id="_2-开发环境与目录" tabindex="-1">2. 开发环境与目录 <a class="header-anchor" href="#_2-开发环境与目录" aria-label="Permalink to &quot;2. 开发环境与目录&quot;">​</a></h2><p>使用根目录 package.json 指定的 Bun 版本。以下命令在仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev:plugins</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bun</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div><p>dev:plugins 构建工具和节点，并同步到开发用 data/。dev 启动 Web 与 Server，不会自动重新构建插件。开发页面默认为 <code>http://localhost:5173</code>，Server 默认监听 <code>3000</code>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>packages/</span></span>
<span class="line"><span>  toolScaffold/        工具构建器与运行时类型</span></span>
<span class="line"><span>  nodeScaffold/        节点构建器与运行时接口</span></span>
<span class="line"><span>  tools/&lt;toolName&gt;/    工具源码</span></span>
<span class="line"><span>  nodes/&lt;nodeName&gt;/    节点源码</span></span>
<span class="line"><span>  skills/&lt;skillName&gt;/  SKILL.md 与附属资源</span></span>
<span class="line"><span>build/</span></span>
<span class="line"><span>  tools/              &lt;toolName&gt;.tool.js</span></span>
<span class="line"><span>  nodes/              &lt;nodeName&gt;.umd.js</span></span>
<span class="line"><span>  skills/             内置技能副本</span></span>
<span class="line"><span>data/</span></span>
<span class="line"><span>  tools/              已安装工具</span></span>
<span class="line"><span>  nodes/              已安装节点</span></span>
<span class="line"><span>  skills/             已安装全局技能</span></span>
<span class="line"><span>  settings.json       设置与插件配置</span></span></code></pre></div><p>build/ 是构建产物，data/ 是运行时安装目录。生产数据位置由宿主决定，不要假定是终端当前目录。工作区局部技能放在当前项目的 skill/，注意这里是单数。</p><h2 id="_3-命名与版本" tabindex="-1">3. 命名与版本 <a class="header-anchor" href="#_3-命名与版本" aria-label="Permalink to &quot;3. 命名与版本&quot;">​</a></h2><ul><li>插件标识、源码目录、自有函数、变量和组件使用小驼峰，例如 echoTool、noteNode、storyReview。Vue 文件按 template → script → style 排列。</li><li>工具文件名为 <code>&lt;toolName&gt;</code>.tool.js，节点文件名为 <code>&lt;nodeName&gt;</code>.umd.js，必须与构建标识一致；不要在文件名中追加版本。</li><li>SKILL.md 是协议固定名称，保留大写。</li><li>tools、nodes 的版本来自插件 package.json.version；skill 的版本来自 frontmatter 的 metadata.version。</li><li>使用完整 SemVer，例如 1.0.0、1.1.0-beta.1。正常覆盖安装要求新版本高于旧版本。</li></ul><h2 id="_4-安装、更新与调试" tabindex="-1">4. 安装、更新与调试 <a class="header-anchor" href="#_4-安装、更新与调试" aria-label="Permalink to &quot;4. 安装、更新与调试&quot;">​</a></h2><ol><li>构建产物，或准备 Skill 主文件与资源包。</li><li>打开“设置 → 插件市场 → 已安装 → 安装插件”。</li><li>检查插件名称、版本与加载错误；有配置时填写并保存，工具和节点需处于启用状态。</li><li>执行一次实际操作，检查输出、失败反馈与取消行为。</li></ol><p>同版本反复调试、降级或旧版本无有效版本号时，在“设置 → 开发者选项 → 手动安装插件”勾选“强制安装（允许覆盖同版本或降级）”。强制安装仍会校验格式。</p><p>安装管理要求从桌面端或 Server 本机发起。开发者选项支持本地文件和 HTTP/HTTPS 文件直链；直链不能包含 URL 用户名密码，也不能返回登录页或 HTML 预览页。下载最多等待 30 秒，最多跟随 5 次重定向。</p><table tabindex="0"><thead><tr><th><strong>类型</strong></th><th><strong>安装格式</strong></th><th><strong>限制</strong></th></tr></thead><tbody><tr><td>tools</td><td>.tool.js</td><td>非空，最多 20 MiB，保留构建元数据和默认导出。</td></tr><tr><td>nodes</td><td>.umd.js</td><td>非空，最多 20 MiB，导出名必须匹配文件名。</td></tr><tr><td>skill</td><td>.md、.zip、.tar、.tar.gz、.tgz</td><td>包及解包总量最多 20 MiB；恰好一个 SKILL.md。</td></tr></tbody></table><p>桌面客户端也支持网页唤起安装，应用会展示信息并要求用户确认：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> installUrl</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> URL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;toonflow://install&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">installUrl.searchParams.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;tool&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">installUrl.searchParams.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">set</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://example.com/plugins/echoTool.tool.js&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.location.href </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> installUrl.href;</span></span></code></pre></div><p>本文开放类型使用 tool、node、skill。普通浏览器开发模式不注册桌面协议。</p><h2 id="_5-运行边界" tabindex="-1">5. 运行边界 <a class="header-anchor" href="#_5-运行边界" aria-label="Permalink to &quot;5. 运行边界&quot;">​</a></h2><p>工具拥有 Server 进程权限；节点在宿主页面执行。优先复用宿主文件、模型、画布与 FFmpeg 能力，不打包真实密钥或本机数据。界面交互和画布操作需要对应页面保持连接。</p><p>配置表单统一使用 @form-create/element-ui 的 JSON 规则。工具配置在 context.config；节点配置在 useNode().config。分别保存于 settings.json 的 toolConfigs 与 nodeConfigs。当前 FFmpeg 使用 ffmpeg(signal?) 工厂接口，具体边界见后文。</p>`,22)])])}const g=a(l,[["render",e]]);export{c as __pageData,g as default};
